# oracle: must-pass
warn <- function(x = x) base::warning(base::simpleWarning("hello"), immediate. = x)
message <- function(x = x) base::message(base::simpleMessage("hello"), appendLF = x)
stop <- function(x = x) base::stop(base::simpleError("hello"), call. = x)
conditional <- function(x = x, flag = FALSE) base::warning(if (flag) x else "hello")
stopifnot(identical(suppressWarnings(warn()), "hello"))
stopifnot(is.null(suppressWarnings(suppressMessages(message()))))
stopifnot(identical(tryCatch(suppressWarnings(stop()), error = conditionMessage), "hello"))
stopifnot(identical(suppressWarnings(conditional()), "hello"))
unary <- function(x = x, flag = FALSE) base::warning(!(if (flag) x else FALSE))
binary <- function(x = x, flag = FALSE) base::warning(1L + (if (flag) x else 2L))
indexed <- function(x = x, flag = FALSE) base::warning((if (flag) x else 1L)[1L])
stopifnot(identical(suppressWarnings(unary()), "TRUE"))
stopifnot(identical(suppressWarnings(binary()), "3"))
stopifnot(identical(suppressWarnings(indexed()), "1"))
